CREATE TABLE cities (
  id uuid PRIMARY KEY,
  geoname_id integer NOT NULL UNIQUE,
  name text NOT NULL,
  ascii_name text NOT NULL,
  folded_name text NOT NULL,
  region text,
  country_code char(2) NOT NULL,
  latitude double precision NOT NULL,
  longitude double precision NOT NULL,
  population integer NOT NULL
);

CREATE INDEX cities_name_prefix_idx ON cities (lower(name) text_pattern_ops);
CREATE INDEX cities_ascii_name_prefix_idx ON cities (lower(ascii_name) text_pattern_ops);
CREATE INDEX cities_folded_name_prefix_idx ON cities (folded_name text_pattern_ops);



































